}

.dark-mode .footer {
  border-top-color: #334155;
}

.clear-btn {
  padding: 8px 16px;
  background: #f1f5f9;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 12px;
}

.dark-mode .clear-btn {
  background: #334155;
  color: #e2e8f0;
}

